EX.push(...[{"id":"iar-2026-cardio","name":"IAR 2026 · CARDIOLOGÍA","year":"IAR 2026 · prueba 88 preguntas","qs":[{"n":1,"q":"El 90% de los aneurismas del ventrículo izquierdo, como complicación de infarto de miocardio transmural, son secundarios a una oclusión aguda de la arteria coronaria:","o":["Tronco de la arteria coronaria izquierda","Arteria descendente anterior","Arteria circunfleja","Arteria coronaria derecha"]},{"n":49,"q":"En paciente con shock cardiogénico monitorizado con catéter de Swan-Ganz, ¿cómo se obtiene la presión capilar pulmonar de enclavamiento (wedge)?","o":["Inflando el balón del catéter en la aurícula derecha","Inflando el balón del catéter en una rama de la arteria pulmonar","Desinflando el balón del catéter en el ventrículo derecho","Colocando el catéter en la arteria femoral"]}]},{"id":"iar-2026-cirugia","name":"IAR 2026 · CIRUGÍA GENERAL","year":"IAR 2026 · prueba 88 preguntas","qs":[{"n":26,"q":"Tras apendicectomía por apendicitis no complicada, anatomía patológica informa tumor neuroendocrino apendicular de 1 cm en la punta, limitado a submucosa y con márgenes negativos. Paciente asintomático. ¿Conducta más apropiada?","o":["Reoperar y realizar hemicolectomía derecha","Controles clínicos periódicos","Radioterapia","Linfadenectomía regional"]}]},{"id":"iar-2026-neumo","name":"IAR 2026 · NEUMOLOGÍA","year":"IAR 2026 · prueba 88 preguntas","qs":[{"n":40,"q":"¿Cuál de las siguientes afirmaciones describe correctamente las funciones de los neumocitos tipo I y tipo II en el pulmón adulto?","o":["Los tipo I producen surfactante y los tipo II forman la barrera alveolocapilar","Los tipo I participan en el intercambio gaseoso y los tipo II producen surfactante y actúan como células progenitoras","Los tipo I secretan moco y los tipo II regulan la presión oncótica alveolar","Los tipo I fagocitan detritos y los tipo II realizan la hematosis"]}]},{"id":"iar-2026-infecto","name":"IAR 2026 · INFECTOLOGÍA","year":"IAR 2026 · prueba 88 preguntas","qs":[{"n":42,"q":"Paciente con catéter venoso central y fiebre: hemocultivos simultáneos periférico y del catéter aíslan el mismo microorganismo; el del catéter se positiviza tres horas antes. ¿Qué sugiere?","o":["Contaminación del hemocultivo","Bacteriemia secundaria a foco urinario","Bacteriemia relacionada con catéter","Endocarditis obligatoria"]}]}]);
Object.assign(KEY["iar-2026-cardio"] ??= {}, {1:{"a":"B","status":"validado","why":"El aneurisma verdadero del ventrículo izquierdo posterior a un infarto transmural aparece clásicamente en la pared anterior y el ápex, territorios irrigados por la arteria descendente anterior. La cifra exacta del 90% depende de la serie estudiada.","o":{"A":"Puede causar infarto extenso, pero no es la localización coronaria clásica de esta complicación.","C":"Irriga principalmente la pared lateral o posterolateral.","D":"Se asocia más habitualmente con infarto inferior o del ventrículo derecho."},"src":"Braunwald's Heart Disease, capítulos de complicaciones mecánicas del infarto."}});
Object.assign(KEY["iar-2026-cirugia"] ??= {}, {26:{"a":"B","status":"validado","why":"Un tumor neuroendocrino apendicular bien diferenciado de 1 cm, completamente resecado, en la punta y sin factores de alto riesgo no requiere hemicolectomía derecha. Entre las opciones, el seguimiento clínico conservador es la más adecuada; en muchos casos ni siquiera se requiere vigilancia específica intensiva. La decisión exige confirmar grado, invasión linfovascular y márgenes.","o":{"A":"La hemicolectomía se reserva para tumores mayores o con características de riesgo seleccionadas.","C":"No es tratamiento habitual del tumor localizado resecado.","D":"No está indicada sin evidencia de enfermedad ganglionar o factores de alto riesgo."},"src":"European Neuroendocrine Tumor Society (ENETS), guidance para tumores neuroendocrinos apendiculares."}});
Object.assign(KEY["iar-2026-neumo"] ??= {}, {40:{"a":"B","status":"validado","why":"Los neumocitos tipo I son células aplanadas que recubren gran parte de la superficie alveolar y facilitan la difusión gaseosa. Los tipo II sintetizan surfactante y pueden proliferar y diferenciarse durante la reparación epitelial.","o":{"A":"Invierte las funciones principales de ambos tipos.","C":"La secreción de moco corresponde a otras células epiteliales, no a los neumocitos I.","D":"La fagocitosis corresponde principalmente a macrófagos alveolares y el intercambio gaseoso ocurre sobre la barrera formada predominantemente por células tipo I."},"src":"Junqueira, Histología básica; fisiología respiratoria alveolar."}});
Object.assign(KEY["iar-2026-infecto"] ??= {}, {42:{"a":"C","status":"validado","why":"Un diferencial de tiempo de positividad de al menos dos horas, con crecimiento del mismo microorganismo en muestras simultáneas del catéter y periférica, apoya bacteriemia relacionada con el catéter; debe interpretarse junto con la clínica y la calidad de la toma.","o":{"A":"El diferencial temporal por sí solo no equivale a contaminación.","B":"No hay datos que señalen foco urinario.","D":"No establece diagnóstico de endocarditis."},"src":"IDSA, Clinical Practice Guidelines for the Diagnosis and Management of Intravascular Catheter-Related Infection."}});
Object.assign(KEY["iar-2026-cardio"] ??= {}, {49:{"a":"B","status":"validado","why":"La presión de enclavamiento se obtiene al inflar brevemente el balón en una rama distal de la arteria pulmonar, con la punta enclavada; en condiciones apropiadas aproxima la presión auricular izquierda y puede estimar la presión de llenado ventricular izquierda.","o":{"A":"La aurícula derecha permite medir presión venosa central, no wedge.","C":"El ventrículo derecho no es el sitio de enclavamiento.","D":"El Swan-Ganz se introduce por vía venosa, no arterial femoral."},"src":"ESC, recomendaciones de monitorización hemodinámica en insuficiencia cardíaca aguda; textos de cateterismo derecho."}});

