/* Agrupar todas las preguntas de Últimas IAR 2026 en UN simulacro de 88 posiciones.
   Mantener el número original; la pregunta 6 no está disponible en el PDF. */
(function(){
  const partes=EX.filter(e=>String(e.year)==="IAR 2026 · prueba 88 preguntas");
  const items=new Map(),claves={};
  for(const e of partes){
    for(const q of e.qs){if(!items.has(q.n))items.set(q.n,q);}
    Object.assign(claves,KEY[e.id]||{});
  }
  const nuevaClave={};
  for(const e of partes){
    for(const q of e.qs){
      const k=(KEY[e.id]||{})[q.n];
      if(k)nuevaClave[q.n]=k;
    }
  }
  for(const e of partes){const idx=EX.indexOf(e);if(idx!==-1)EX.splice(idx,1);}
  EX.push({id:"iar-2026-completo",name:"Últimas IAR 2026 · examen integrado",year:"IAR 2026 · prueba 88 preguntas",qs:[...items.values()].sort((a,b)=>a.n-b.n)});
  KEY["iar-2026-completo"]=nuevaClave;
})();

/* Auditoría científica por pregunta — preservar trazabilidad y no puntuar claves aún no verificadas. */
(function(){
const key=KEY['iar-2026-completo'];
const fixes={"8":{"status":"discutible","why":"El cuadro es altamente compatible con toxoplasmosis cerebral. El PDF ofrece pirimetamina+sulfadiazina+ÁCIDO FÓLICO, pero la prevención de mielotoxicidad requiere ácido FOLÍNICO (leucovorina). Además, TMP-SMX en dosis terapéuticas es una alternativa aceptada. Por ello no debe puntuarse con clave única.","o":{"A":"Anfotericina B más flucitosina se utiliza para criptococosis, no toxoplasmosis cerebral.","B":"La asociación es correcta solo si el rescate hematológico es ácido folínico (leucovorina), no ácido fólico.","C":"TMP-SMX en dosis terapéuticas es alternativa eficaz y recomendada; la palabra monoterapia es imprecisa porque combina dos principios activos.","D":"Ganciclovir se utiliza frente a citomegalovirus, no Toxoplasma."},"src":"NIH HIV Opportunistic Infections Guidelines — Toxoplasma gondii Encephalitis","src_url":"https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/toxoplasma-gondii-encephalitis"},"18":{"status":"validado","why":"En infección por C. difficile grave no fulminante, la fidaxomicina es preferida cuando está disponible, pero vancomicina oral 125 mg cuatro veces al día durante 10 días sigue siendo una alternativa adecuada y es la única opción correcta entre las ofrecidas. No usar vancomicina IV para colitis por C. difficile.","o":{"B":"Metronidazol oral es inferior y no es primera línea para CDI grave.","C":"Ciprofloxacina no trata CDI y puede favorecerla.","D":"Rifaximina aislada no es tratamiento inicial recomendado; puede considerarse en esquemas de recurrencia seleccionados."},"src":"AGA Clinical Practice Update on CDI (2026); IDSA/SHEA 2021","src_url":"https://pubmed.ncbi.nlm.nih.gov/42383946/"},"19":{"status":"validado","why":"La guía consensuada AAN/AAP/CNS/SCCM indica suspender prueba de apnea ante inestabilidad hemodinámica (PAS <100 o PAM <75 pese a soporte), desaturación progresiva <85%, arritmia con inestabilidad o respiración espontánea. La opción B es la mejor entre las propuestas.","o":{"A":"La prueba se realiza tras preoxigenación con oxígeno al 100%; el umbral consensuado de interrupción es desaturación progresiva <85%, no simplemente <90% con FiO2 0,21.","C":"Movimientos reflejos espinales no equivalen necesariamente a respiración; actividad convulsiva requiere reconsiderar el diagnóstico, pero no es el criterio protocolizado mejor expresado aquí.","D":"Frecuencia cardíaca >105/min aislada no es criterio de interrupción."},"src":"AAN/AAP/CNS/SCCM 2023 Brain Death Consensus Guideline","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10791061/"},"21":{"status":"discutible","why":"La sospecha principal es meningococo por edad, meningitis aguda y exantema, pero el PDF informa PROTEÍNAS BAJAS en LCR, dato atípico de meningitis bacteriana (habitualmente elevadas). Requiere corregir el dato original antes de puntuar.","o":{"A":"Neumococo también causa meningitis bacteriana, pero el exantema sugiere meningococo.","B":"Listeria es más frecuente en neonatos, mayores e inmunodeprimidos.","D":"H. influenzae puede causar meningitis, pero la epidemiología y el exantema favorecen meningococo."}},"22":{"status":"discutible","why":"El parámetro espirométrico de referencia para demostrar obstrucción es la relación VEF1/CVF (con LLN o umbral contextual), no el VEF1 aislado. Como VEF1/CVF no figura entre opciones, A es solo la mejor alternativa disponible, no una definición completa.","o":{"B":"Volumen residual puede aumentar por atrapamiento, pero no define obstrucción.","C":"Volumen de reserva espiratoria no es criterio diagnóstico de obstrucción.","D":"Capacidad pulmonar total mide volumen estático, no obstrucción al flujo."}},"38":{"status":"discutible","why":"La ferropenia está demostrada y el hierro oral es apropiado, pero sulfato ferroso 325 mg cada 8 horas es un esquema innecesariamente frecuente y menos tolerable; se prefiere a menudo una dosis diaria o en días alternos. Mantener sin puntuación hasta revisar intención del examen.","o":{"A":"Transfusión no se indica por Hb 8,9 g/dL en paciente estable sin otros criterios.","B":"Hierro IV se reserva según intolerancia, mala absorción, necesidad rápida o fracaso de vía oral.","D":"Ácido fólico no corrige déficit de hierro."}},"55":{"status":"discutible","why":"Megacolon tóxico en colitis ulcerosa requiere hospitalización, reanimación, esteroides IV, evaluación quirúrgica precoz y cirugía urgente ante perforación, deterioro o falta de respuesta. El enunciado no caracteriza claramente el tiempo ni la gravedad del fracaso; la ciclosporina puede ser rescate en casos seleccionados.","o":{"B":"Azatioprina tiene inicio lento y no resuelve megacolon agudo.","C":"Ciclosporina IV es rescate posible en colitis aguda grave refractaria en pacientes seleccionados sin indicación inmediata de cirugía.","D":"Sulfasalazina oral no es tratamiento del megacolon tóxico."}},"83":{"status":"discutible","why":"En trauma con hemorragia externa catastrófica, se prioriza controlar la hemorragia inmediatamente (xABCDE/C-ABC), junto a manejo urgente de vía aérea comprometida. Ninguna opción expresa claramente la secuencia adecuada de ambas intervenciones.","o":{"A":"Imagen y osteosíntesis no preceden la reanimación.","B":"Controlar sangrado es correcto, pero luego debe abordarse vía aérea, no saltar a evaluación neurológica.","C":"Inmovilización no antecede control de hemorragia masiva.","D":"Asegurar vía aérea es crítico, pero omite control inicial simultáneo de hemorragia exanguinante."}},"87":{"status":"discutible","why":"El síndrome de vena cava superior requiere evaluar compromiso respiratorio/cerebral y TC de tórax con contraste. En obstrucción amenazante puede requerirse stent urgente; tratamiento oncológico depende de histología. No se indica radioterapia o corticoide universalmente antes de diagnóstico, y las opciones mezclan estudios y tratamientos.","o":{"A":"RM no es obligatoria y la urgencia puede requerir intervención antes de biopsia.","B":"Radioterapia inmediata no es universal y RM no es el estudio inicial preferido.","C":"TC es adecuada, pero corticoides/radioterapia no son automáticos para todos los casos.","D":"Imagen contrastada es importante, pero la opción no incorpora evaluación ni estabilización urgente."}}};
for(const [n,v] of Object.entries(fixes)){if(key[n])Object.assign(key[n],v);}
for(const [n,k] of Object.entries(key)){if(k.status==="validado" && (String(k.src||"").includes("Revisión clínica 2026; verificar") || Object.values(k.o||{}).some(t=>/No es la (opción más apropiada|mejor respuesta)/.test(t)))){k.status="provisional";k.why=(k.why||"")+" [AUDITORÍA: aún no se ha contrastado individualmente cada alternativa con una fuente específica; no se puntúa.]";}}
})();

