(function(){const k=KEY["iar-2026-completo"];const d={"1":{"o":{"A":"El tronco izquierdo puede producir un infarto extenso, pero el aneurisma ventricular postinfarto típico es anterior/apical por afectación de la descendente anterior.","C":"La circunfleja suele irrigar territorio lateral o posterolateral, no el anterior/apical predominante.","D":"La coronaria derecha suele comprometer territorio inferior y, según dominancia, posterior."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK555955/"},"2":{"o":{"A":"Dermatitis atópica no es la dermatosis autoinmune específica vinculada a enfermedad celíaca.","C":"Granuloma anular no es la asociación cutánea clásica de celiaquía.","D":"Rosácea no corresponde a la manifestación cutánea específica mediada por depósitos de IgA."},"src_url":"https://www.niddk.nih.gov/health-information/digestive-diseases/dermatitis-herpetiformis"},"4":{"o":{"B":"Los corticoides sistémicos se utilizan en exacerbaciones moderadas-graves, habitualmente cursos breves.","C":"Los antibióticos pueden estar indicados por purulencia del esputo y criterios clínicos o ventilación.","D":"Ipratropio es broncodilatador de acción corta apropiado, a menudo junto a agonista beta-2."},"src_url":"https://goldcopd.org/"},"5":{"o":{"A":"Glucocorticoides solos no controlan de manera sostenida la progresión estructural de artritis reumatoide.","B":"Hidroxicloroquina puede considerarse en actividad baja; con poliartritis activa seropositiva metotrexato suele preferirse.","D":"Biológicos anti-TNF no son de primera elección habitual en paciente sin ensayo previo de FAME convencional."},"src_url":"https://rheumatology.org/rheumatoid-arthritis-guideline"},"7":{"o":{"B":"Inmunosupresión inespecífica no es primera línea en espondiloartritis axial.","C":"FAME convencionales como metotrexato no tienen eficacia demostrada para enfermedad axial aislada.","D":"No hay indicios de infección bacteriana que requiera antibióticos."},"src_url":"https://ard.bmj.com/content/82/1/19"},"9":{"o":{"A":"La cifra sistólica aislada no permite diferenciar urgencia de emergencia hipertensiva.","B":"La PAM ayuda a orientar reducción controlada cuando corresponde, pero no sustituye evaluar lesión orgánica.","C":"Fondo de ojo puede ser útil; la función hepática aislada no es la prioridad frente a posibles complicaciones neurológicas, cardíacas o renales."},"src_url":"https://www.heart.org/en/health-topics/high-blood-pressure"},"10":{"o":{"A":"Glasgow mide nivel de conciencia, no riesgo de hepatotoxicidad según concentración-tiempo.","B":"No existe un índice validado con ese nombre para decidir NAC según nivel plasmático.","C":"Poisoning Severity Score describe gravedad global, no reemplaza el nomograma para ingesta única de hora conocida."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK441917/"},"11":{"o":{"A":"El bloqueo nicotínico competitivo no explica el síndrome colinérgico muscarínico y nicotínico.","B":"Inhibir MAO produce otra toxidromia, no broncorrea, miosis y fasciculaciones típicas.","C":"Bloqueo de canales de sodio se asocia con otros tóxicos y alteraciones de conducción."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK470430/"},"12":{"o":{"A":"Anticuerpos y linfocitos B no son el mecanismo predominante de organización del granuloma tuberculoso.","B":"Neutrófilos participan en inflamación, pero no constituyen la respuesta granulomatosa adaptativa central.","C":"El complemento no sustituye el eje Th1/IFN-gamma/macrófagos."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK441916/"},"13":{"o":{"A":"Formaldehído es intermediario de vida corta; la acumulación de formiato explica la mayor parte de acidosis y daño ocular.","B":"Lactato puede elevarse secundariamente, pero no es el metabolito tóxico específico del metanol.","D":"Acetaldehído es metabolito del etanol, no el principal tóxico del metanol."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK482121/"},"14":{"o":{"A":"Sepsis es disfunción orgánica por respuesta desregulada a infección; la necesidad de vasopresores con hiperlactatemia apunta a su subgrupo de shock.","B":"Bacteriemia es presencia de bacterias en sangre y no describe por sí sola fracaso circulatorio.","D":"SIRS es una respuesta inflamatoria inespecífica y no define shock séptico."},"src_url":"https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines"},"15":{"o":{"A":"Poliarteritis nodosa afecta vasos medianos y no suele causar glomerulonefritis ni PR3-ANCA.","B":"Behçet se asocia típicamente con aftas recurrentes y otras manifestaciones mucocutáneas/vasculares.","C":"Vasculitis crioglobulinémica suele asociarse con púrpura, neuropatía, glomerulonefritis y crioglobulinas; PR3-ANCA y afectación ORL-pulmonar favorecen GPA."},"src_url":"https://www.ncbi.nlm.nih.gov/books/NBK557827/"},"16":{"o":{"A":"CD4 <500 implica inmunosupresión, pero no es el umbral clásico de riesgo elevado de neumocistosis.","B":"CD4 <350 tampoco es el punto de corte habitual para profilaxis primaria de Pneumocystis.","D":"CD4 <100 conlleva riesgo aún mayor, pero el incremento importante comienza clásicamente por debajo de 200."},"src_url":"https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/pneumocystis"},"17":{"o":{"A":"Rodilla puede afectarse, especialmente en gota poliarticular, pero es menos clásica que primera metatarsofalángica.","B":"Tobillo es localización frecuente, aunque no la presentación prototípica de podagra.","C":"Cadera se afecta con mucha menor frecuencia en un primer ataque."},"src_url":"https://www.niams.nih.gov/health-topics/gout"}};for(const [n,v] of Object.entries(d)){if(!k[n])continue;Object.assign(k[n],v);if(k[n].status==="provisional"&&k[n].a)k[n].status="validado";}})();

